create function copel_private.runtime_status() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or copel_private.access_role() is null then raise exception 'Acesso não autorizado.' using errcode='42501'; end if; return jsonb_build_object('scheduler',exists(select 1 from cron.job where jobname='copel-verificar-prazos' and active),'lastCheck',(select max(at) from public.copel_runs)); end $$; revoke all on function copel_private.runtime_status() from public,anon; grant execute on function copel_private.runtime_status() to authenticated; create function public.copel_runtime_status() returns jsonb language sql stable security invoker set search_path='' as $$select copel_private.runtime_status()$$; revoke all on function public.copel_runtime_status() from public,anon; grant execute on function public.copel_runtime_status() to authenticated;
